const html = fs.readFileSync(SRC, 'utf8');
const pl = fs.readFileSync(path.join(OUT, 'app/planner.js'), 'utf8');
const tmp = fs.mkdtempSync('/tmp/claude-0/mut-'); fs.mkdirSync(path.join(tmp, 'app'));
let caught = 0, survived = [];
const ONLY = process.env.MUT_ONLY ? process.env.MUT_ONLY.split('|') : null;
for (const [name, a, b, test, target] of M) {
  if (ONLY && !ONLY.includes(name)) continue;
  const src = target === 'planner' ? pl : html;
  const n = src.split(a).length - 1;
  if (n !== 1) { console.log('  BAD MUTANT (found ' + n + '×):', name); survived.push(name + ' (bad)'); continue; }
  fs.writeFileSync(path.join(tmp, 'app', 'index.html'), target === 'planner' ? html : html.replace(a, b));
  fs.writeFileSync(path.join(tmp, 'app', 'planner.js'), target === 'planner' ? pl.replace(a, b) : pl);
  let failed = false, out = '';
  try { execFileSync('node', ['check-app.mjs', '--quiet', '--only', test], { env: { ...process.env, APP_DIR: tmp }, stdio: 'pipe', timeout: 300000 }); }
  catch (e) { failed = true; out = String(e.stdout || '') + String(e.stderr || ''); }
  /* only a test that ran and failed counts as caught — a crashed run (port in use, timeout) is not */
  if (failed && (!/check-app: \d+ passed, [1-9]\d* failed/.test(out) || /EADDRINUSE/.test(out))) { console.log('  BROKE   ', name, '— the run crashed; rerun it'); survived.push(name + ' (broke)'); continue; }
  if (failed) { caught++; console.log('  caught  ', name); } else { survived.push(name); console.log('  SURVIVED', name); }
}
console.log(`\nmutations: ${caught}/${M.length} caught`);
if (survived.length) { console.log('survived:', survived.join(' | ')); process.exit(1); }
